// PROFESSIONAL EXPANSION
const LESSON_PROCEDURES={"role": ["Specify the professional responsibility, domain, and decision to support.", "Describe what the audience already understands and the depth it needs.", "Define the evidence standard and output criteria independently of the role."], "zero": ["State a bounded task with explicit inputs and label definitions.", "Specify the output and missing-information behavior.", "Test a simple, ambiguous, and incomplete case before adding demonstrations."], "one": ["Choose a representative, correct input\u2013output pair.", "Explain which properties the example demonstrates: structure, reasoning summary, or style.", "Delimit the example and the actual input; check the output did not copy example facts."], "few": ["Choose diverse examples that reflect real label boundaries.", "Include missing information, difficult negatives, and an unknown case.", "Keep the examples consistent; evaluate on different held-out records."], "structure": ["Define fields, types, units, enum values, and required versus optional data.", "Use native structured-output controls if supported; validate output externally.", "Separate schema errors from factual errors and set a retry or review policy."], "grounding": ["Identify authoritative sources, revision rules, and user access permissions.", "Retrieve passages with sufficient context and preserve source IDs.", "Check support for each claim and evaluate retrieval failures separately from generation errors."], "decompose": ["Map the task into extraction, calculation, interpretation, and reporting.", "Specify a deliverable and validation gate at every boundary.", "Stop or request evidence when a prerequisite fails rather than propagating a guess."], "cot": ["Define the required answer, available facts, and assumptions to disclose.", "Request concise calculations or a checkable explanation; respect model-specific reasoning guidance.", "Verify results using evidence or a separate deterministic calculation."], "consistency": ["Specify how an answer will be normalized and compared before sampling.", "Run independent model calls with suitable settings and record final answers.", "Aggregate only comparable answers; investigate disagreement and verify the selected result."], "tree": ["Represent the initial state, permitted moves, hard constraints, and termination rule.", "Generate candidate next states and evaluate them against explicit criteria.", "Prune or backtrack when branches fail; validate the final plan using external evidence."], "chain": ["Define each stage with one goal and a clear input/output contract.", "Validate intermediate artifacts and retain traceability to original sources.", "Handle timeouts, invalid output, and review gates explicitly before advancing."], "critique": ["Write a rubric with observable criteria and examples of failure.", "Have the reviewer quote a problem and the evidence for each proposed fix.", "Revise affected passages and verify that the revision did not introduce new errors."], "react": ["List permitted tools, typed arguments, and read/write boundaries.", "Have the application execute permitted actions and return observed results.", "Check observations before the next action and require authorization for consequential writes."], "eval": ["Define task success and critical failure categories before comparing versions.", "Build a representative held-out set, including rare and adversarial cases.", "Record prompt, model, settings, cost, latency, and results; inspect regressions by failure type."], "image": ["Specify subject, spatial relationships, viewpoint, composition, and intended use.", "Choose lighting and style that make the important information visible.", "Iterate one visual variable at a time and inspect geometry, references, and unintended changes."], "reference": ["Provide an authorized reference and identify the exact change.", "List invariants such as layout, viewpoint, identity, and part count; use masks if available.", "Compare output with the reference and correct drift before making subsequent edits."], "video": ["Describe a single subject action and one dominant camera behavior per shot.", "Set framing, environment, reference, duration, and visual style using supported controls.", "Inspect motion, continuity, and physical plausibility; regenerate weak shots separately."], "continuity": ["Create a shot list with objective, duration, action, camera, and transition.", "Build a continuity sheet for subject, setting, palette, light, and reference frames.", "Assemble clips, check transitions, and add verified text or measurements during editing."], "injection": ["Identify every untrusted input: documents, retrieved pages, messages, and tool results.", "Keep content separate from trusted instructions and constrain tool permissions in code.", "Test representative attacks and check both the answer and any attempted downstream actions."], "leaking": ["Classify configuration and data by sensitivity; remove secrets from model context.", "Enforce access controls before retrieval and minimize privileged context.", "Test disclosure attempts and inspect logs for exact and paraphrased leakage."], "jailbreak": ["Define the permitted task and the application\u2019s behavior boundaries.", "Use authorized tests that cover reframing, role-play, and instruction conflicts.", "Measure actual boundary violations; fix application controls and retest variants."]};
const LESSON_DEPTH={"role": "A good role brief identifies what to prioritize: traceability and measurement uncertainty for quality engineering, rather than persuasive confidence. Keep the audience separate: the same evidence can support a technician checklist or a management decision brief.", "zero": "Zero-shot is a useful baseline. If the task fails, inspect whether the label definitions or evidence are missing before assuming you need a more elaborate technique. More prompt text can add ambiguity as readily as it adds guidance.", "one": "One-shot is economical when the target format is unusual but the transformation is straightforward. It can accidentally teach incidental properties: an example containing one defect does not mean every record has exactly one defect.", "few": "Examples influence the interpretation of a task without updating weights. Their coverage matters more than a magic number. Track class balance and avoid examples that leak the answers to your evaluation set.", "structure": "An output contract connects language generation to software. A field can be syntactically valid while representing an unsupported measurement, so validate business rules and evidence in addition to JSON syntax.", "grounding": "A retrieval pipeline can fail before the model writes anything. Examine whether the correct document was retrieved, whether the required clause fit in context, and whether the generated claim follows from it. A citation is an audit handle, not a correctness certificate.", "decompose": "Decomposition helps when subtasks require different tools or verification. Preserve dependencies: classifying a downtime event should not erase the original timestamp used to calculate duration. Extra stages are useful only if they make a failure easier to detect or prevent.", "cot": "Chain-of-thought research includes demonstrations containing intermediate steps and zero-shot variants. Modern reasoning models may already perform internal reasoning. Request the externally useful work\u2014assumptions, formulas, results, and checks\u2014rather than private internal reasoning.", "consistency": "The method trades additional inference cost for a more robust selection process on some tasks. Independent samples may still share systematic errors or faulty premises. Confidence should depend on external validation, not vote count alone.", "tree": "A real search process needs a state representation, branching policy, evaluator, and budget. For physical manufacturing plans, feasibility depends on geometry, access, timing, and safety constraints that a language model may not reliably judge by itself.", "chain": "A chain is operational architecture, not just a numbered list inside one prompt. It can use multiple model calls, ordinary code, retrieval, and human review. Preserve artifacts so a downstream error can be traced to its origin.", "critique": "A critique step works best with a stable rubric and access to the actual source material. Self-criticism without new evidence can reinforce an initial mistake or introduce unnecessary rewrites. Ask for justified, localized changes.", "react": "Tool outputs become new evidence for the next decision. The surrounding application\u2014not the model\u2019s role description\u2014must enforce permissions, argument validation, rate limits, logging, and approval for writes.", "eval": "A reusable prompt is a maintained component. Version the prompt and test data, pin model configuration where possible, and define a minimum performance threshold for critical cases. Aggregate scores alone can hide unacceptable regressions.", "image": "For technical communication, composition should serve the message: distinguish the inspected part from the scanner, show the relevant viewpoint, and leave room for labels. Generated diagrams and geometry require expert checking; exact drawings belong in CAD or vector tools.", "reference": "Reference conditioning and editing behavior differ across products and models. \u201cPreserve everything else\u201d expresses intent but is not a guarantee. Review the entire output, especially repeated objects, edges, dimensions, and background details.", "video": "Too many simultaneous actions make control difficult. Start with a short coherent shot and distinguish subject motion from camera motion. A visible scanning effect may be an illustrative convention rather than the physical behavior of a real sensor.", "continuity": "Continuity is both a prompting and an editing task. Matching references can improve consistency, but scene geometry, clothing, robot position, and illumination may still drift. Verify every shot and the transitions between them.", "injection": "Injection exploits a trust-boundary failure: an application treats attacker-controlled content as an instruction. The payload can look like normal prose, a quoted instruction, or tool output. Defenses need layered application controls, not just a stronger system prompt.", "leaking": "The objective is unauthorized disclosure of hidden instructions or sensitive context. Hidden prompts should not be treated as a secure vault. Even apparently harmless configuration can expose internal workflow assumptions, so disclose only what the product intends to share.", "jailbreak": "Jailbreaking describes attempts to bypass behavioral safeguards; prompt injection describes how untrusted instructions enter a workflow. The concepts overlap, but an injection can target an ordinary business rule or exfiltrate data without requesting otherwise prohibited content."};
for(const t of TECHNIQUES){t.group=["Reasoning","Workflows"].includes(t.category)?t.category:"General";if(t.category==="Foundations")t.category="Foundational";if(["Reasoning","Workflows"].includes(t.category))t.category="Text";t.steps=LESSON_PROCEDURES[t.id];t.depth=LESSON_DEPTH[t.id];t.related=t.category==="Security"?["injection","leaking","jailbreak"].filter(id=>id!==t.id):t.category==="Image"?["image","reference","eval"].filter(id=>id!==t.id):t.category==="Video"?["video","continuity","reference"].filter(id=>id!==t.id):["structure","grounding","eval"].filter(id=>id!==t.id);}
TECHNIQUES.push({"id": "spec-first", "name": "Specification-first coding", "category": "Coding", "level": "Applied", "group": "General", "summary": "Turn a vague feature request into an explicit behavior contract.", "what": "Turn a vague feature request into an explicit behavior contract.", "when": "When implementing a new feature or changing public behavior.", "steps": ["Define inputs, outputs, failure cases, and compatibility constraints.", "Write observable acceptance criteria and clarify material ambiguities.", "Ask for the implementation plan, then implement against the agreed contract."], "example": "Implement a parser for scanner CSV records. Required columns: part_id, feature_id, measured_mm. Reject duplicate column names and non-finite measurements. Preserve row order. Return valid records plus row-specific errors; never silently skip invalid rows. Provide acceptance examples before implementation.", "limit": "A detailed specification can still encode the wrong product behavior. Confirm requirements with domain owners.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["structure", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "repo-context", "name": "Repository context", "category": "Coding", "level": "Applied", "group": "General", "summary": "Ground code changes in the actual project architecture and conventions.", "what": "Ground code changes in the actual project architecture and conventions.", "when": "When editing an existing codebase.", "steps": ["Read project instructions, dependency manifests, relevant entry points, and tests.", "Identify the exact module and neighboring patterns before proposing changes.", "Cite affected files and verify actual APIs rather than inventing integration points."], "example": "Inspect the inspection-dashboard repository. Identify how CSV imports reach the results table, the existing validation utilities, and the test command. Then add the new measured_mm validation using the established patterns. Do not assume filenames or dependencies.", "limit": "A repository summary can be stale. Verify the current files and avoid pulling unnecessary secrets into context.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["grounding", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "minimal-diff", "name": "Minimal-diff changes", "category": "Coding", "level": "Applied", "group": "General", "summary": "Constrain the implementation to the smallest coherent change.", "what": "Constrain the implementation to the smallest coherent change.", "when": "Bug fixes and maintenance in stable production code.", "steps": ["Define the failing behavior and files likely to own it.", "Set preservation constraints for public APIs, layout, and unrelated behavior.", "Review the actual diff and remove unrelated churn while keeping the solution complete."], "example": "Fix the empty-filter crash in the defect table. Preserve existing sorting, pagination, and public interfaces. Reuse existing utilities. Avoid unrelated formatting changes. Explain each modified file and how the fix was verified.", "limit": "Smallest line count is not the same as safest design. A coherent fix may require several files.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["critique", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "debug-repro", "name": "Reproduction-led debugging", "category": "Coding", "level": "Applied", "group": "General", "summary": "Start with an observable failure and test competing hypotheses.", "what": "Start with an observable failure and test competing hypotheses.", "when": "Intermittent errors, incorrect results, and regressions.", "steps": ["Collect expected versus actual behavior, logs, environment, and a minimal reproduction.", "Trace the failing path and rank hypotheses using evidence.", "Fix the demonstrated cause and rerun the reproduction plus relevant regression checks."], "example": "The capacity report shows 800 instead of 80 units/hour for a 45-second cycle. Reproduce with this input, trace unit conversion, identify the exact cause, and propose a patch. Show the confirming calculation and a regression case; do not guess from the error message alone.", "limit": "Logs may contain confidential production data. Use the minimum relevant sanitized evidence.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["decompose", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "tests-first", "name": "Acceptance tests first", "category": "Coding", "level": "Applied", "group": "General", "summary": "Express important behavior as executable examples before implementation.", "what": "Express important behavior as executable examples before implementation.", "when": "Business logic with precise requirements or a reproduced bug.", "steps": ["Derive tests from the requirements, including boundary and failure cases.", "Check that the tests would fail for the known wrong behavior.", "Implement, run relevant tests, and inspect whether the suite verifies meaningful outcomes."], "example": "Before changing tolerance evaluation, add tests for lower bound, upper bound, just outside each bound, missing tolerance, and unit mismatch. Use the approved inclusive-bound rule. Then implement the smallest change that satisfies these cases.", "limit": "Passing self-written tests is not proof. Tests can repeat the same misunderstanding as the implementation.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["eval", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "code-review", "name": "Risk-focused code review", "category": "Coding", "level": "Applied", "group": "General", "summary": "Review actual changes against behavioral and operational risks.", "what": "Review actual changes against behavioral and operational risks.", "when": "Before merging changes or auditing unfamiliar code.", "steps": ["Read the diff and surrounding code paths.", "Prioritize reproducible bugs, security issues, data loss, and missing edge cases.", "Report location, impact, evidence, and a concrete fix; distinguish findings from questions."], "example": "Review this scanner-ingestion diff for incorrect unit conversions, dropped records, duplicate handling, and unsafe file access. For each finding include the affected code, a failing example, severity rationale, and a suggested correction. Do not invent findings to meet a quota.", "limit": "Review quality depends on available context and execution. Explicitly report what was not verified.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["critique", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "safe-refactor", "name": "Behavior-preserving refactoring", "category": "Coding", "level": "Applied", "group": "General", "summary": "Improve internal structure while explicitly preserving observable behavior.", "what": "Improve internal structure while explicitly preserving observable behavior.", "when": "Reducing duplication or improving maintainability.", "steps": ["Record existing interfaces and behavior with meaningful characterization tests.", "Specify allowed structural changes and forbidden behavior changes.", "Refactor incrementally and compare outputs on representative inputs."], "example": "Extract shared measurement-unit conversion from these importers. Preserve rounding policy, exception types, field names, and accepted input formats. Add characterization cases for current behavior before refactoring. Report any existing inconsistency separately.", "limit": "Existing behavior may include bugs. Do not silently fix them inside a preservation-only refactor.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["minimal-diff", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "tool-contracts", "name": "Typed tool contracts", "category": "Coding", "level": "Applied", "group": "General", "summary": "Design tool calls as validated interfaces, not free-form intentions.", "what": "Design tool calls as validated interfaces, not free-form intentions.", "when": "Connecting model output to databases, services, or code execution.", "steps": ["Define typed arguments, enum values, required fields, and authorization boundaries.", "Validate inputs and business rules before executing any effect.", "Return structured success/error results and test malformed or unauthorized requests."], "example": "Design a read-only lookup_inspection tool accepting part_id and approved_revision. Reject additional fields and invalid IDs. Enforce caller access before querying. Return measurements with units and source IDs; no credentials or arbitrary SQL. Provide schema and negative test cases.", "limit": "Schema validation does not authorize an action. Access control and parameterized queries remain application responsibilities.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["react", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "dependency-grounding", "name": "Dependency-aware implementation", "category": "Coding", "level": "Applied", "group": "General", "summary": "Use the APIs and versions actually installed.", "what": "Use the APIs and versions actually installed.", "when": "Framework integrations and version-sensitive code.", "steps": ["Inspect the lockfile, runtime version, and local type definitions.", "Consult official documentation for the exact dependency version when needed.", "Implement with existing capabilities and verify build/type checks."], "example": "Add a chart to this production dashboard using the installed chart library. First inspect its version and existing usage. Avoid introducing another chart dependency. Verify axis units, empty datasets, and the documented update API.", "limit": "Documentation for the latest version may not match the repository. Do not claim a build passed without running it.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["repo-context", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TECHNIQUES.push({"id": "code-handoff", "name": "Evidence-based code handoff", "category": "Coding", "level": "Applied", "group": "General", "summary": "Make the implementation easy to inspect and maintain.", "what": "Make the implementation easy to inspect and maintain.", "when": "Completing a code task or preparing a review.", "steps": ["Summarize the behavior change and why it was necessary.", "List the checks actually run and their outcomes.", "Identify unresolved constraints and provide a concise reproducible verification path."], "example": "After implementing the scanner import fix, summarize changed behavior, affected modules, test commands actually run, and any unverified edge cases. Include a sample input and expected output for manual verification. Separate completed work from recommendations.", "limit": "A confident summary is not evidence. Preserve failed checks and material limitations rather than hiding them.", "source": "openai", "depth": "Use the assistant as a collaborator with explicit evidence and boundaries. Give it the relevant code and environment, ask it to inspect before changing, and distinguish proposed checks from checks actually executed. Prefer concrete acceptance criteria over requests for \u201cclean\u201d or \u201cproduction-ready\u201d code.", "related": ["eval", "eval"], "exercise": "Adapt the example to one real module and define an observable pass/fail criterion."});
TRICKS.push(...[["Define acceptance criteria", "Expert workflow", "Replace vague quality language with observable checks.", "For extraction: every output row must preserve its source record ID and units."], ["Separate configuration from task data", "Expert workflow", "Keep reusable application behavior in trusted configuration and per-request material in the user input.", "A retrieved supplier note does not get to redefine assistant permissions."], ["Keep a failure ledger", "Evaluate & version", "Record the failure type, input, prompt version, model, and correction.", "Track unit errors separately from missed retrieval and unsupported conclusions."], ["Budget the workflow", "Expert workflow", "Measure latency and cost before adding branches, reviewers, or repeated samples.", "Use deterministic code for capacity arithmetic instead of five model calls."], ["Preserve provenance", "Essential for reliability", "Carry source IDs and revisions through every stage.", "A summary claim should link back to the exact inspection record."], ["Bound the change", "Coding workflow", "Describe the intended behavior change and what must remain compatible.", "Fix parser validation while preserving CSV column names and public interfaces."], ["Ask for missing inputs early", "Expert workflow", "Have the model identify information required to perform the task correctly.", "Request the approved tolerance revision before evaluating conformity."], ["Retest after changes", "Evaluate & version", "Re-run representative cases after model, prompt, data, or tool changes.", "A previously reliable classifier can drift when its label definitions change."]]);
RECIPES.push({"id": "code-import", "title": "Scanner CSV validation", "type": "Coding", "tag": "Software", "role": "Software engineer maintaining a manufacturing data pipeline", "task": "Implement validation for scanner CSV imports using the existing repository conventions.", "context": "Repository: [provide relevant files]. Schema: part_id, feature_id, measured_mm. Runtime and dependencies: [inspect]. Expected error handling: [define].", "audience": "Software and manufacturing data engineers", "constraints": "Inspect existing code first. Reject non-finite measurements and duplicate columns. Preserve row order and public interfaces. Do not silently drop invalid records.", "format": "Implementation plus meaningful boundary tests. Summarize behavior, checks actually run, and unresolved limitations."});

