const CODING_DEPTH={"spec-first": "The specification should distinguish a requirement from an implementation choice. For a scanner importer, accepting finite decimal values is a behavior; choosing a particular parser library is a design choice. Resolve missing domain rules before coding rather than embedding guesses in tests.", "repo-context": "Repository context includes more than the target function: callers, error conventions, configuration, generated files, and test fixtures can determine the correct change. Ask the assistant to identify the relevant path through the system, then read that path rather than dumping the entire repository.", "minimal-diff": "A focused diff reduces review burden and regression surface. State the behavior that must change and the interfaces that must remain stable. Avoid requiring a one-file patch if validation and a regression test naturally belong in separate modules.", "debug-repro": "Separate observations from hypotheses. A capacity result off by a factor of ten suggests a unit or scaling issue, but the exact cause needs a reproducible input and trace through the calculation. Use a failing case to discriminate between competing explanations.", "tests-first": "Acceptance tests translate domain rules into observable outcomes. Include boundary conditions and invalid inputs, then confirm the tests fail for the previous behavior. Avoid tests that merely assert an internal helper was called or mirror the implementation line by line.", "code-review": "A useful review prioritizes findings by impact and confidence. Ask for a concrete failing input, affected behavior, and code location; this keeps the review anchored in evidence. Style preferences should not obscure correctness, data integrity, or authorization problems.", "safe-refactor": "Refactoring deliberately separates structure from behavior. Characterization tests capture existing output, errors, and edge cases before changes. If current behavior is inconsistent or wrong, surface that as a separate decision rather than silently changing it during cleanup.", "tool-contracts": "Tool contracts connect probabilistic generation to deterministic execution. Restrict the allowed operation, validate arguments, enforce caller permissions, and return stable error shapes. Neither a schema nor a system instruction replaces authorization at the data boundary.", "dependency-grounding": "AI-generated code can use a valid API from the wrong version. Ground implementation in the lockfile, installed types, and existing patterns. Verify the exact version before consulting documentation, and avoid dependency additions when the current stack already supplies the capability.", "code-handoff": "A handoff should let another engineer verify the change without replaying the entire conversation. Lead with resulting behavior, give the commands actually run and their outcomes, and expose any unverified assumptions. Keep proposed future work separate from completed implementation."};for(const t of TECHNIQUES)if(CODING_DEPTH[t.id])t.depth=CODING_DEPTH[t.id];

const LESSON_ACCEPTANCE={role:'The output uses the reader’s vocabulary, prioritizes relevant engineering decisions, and does not claim authority merely because of the assigned role.',zero:'Every record has an allowed label, supporting text, and unknown where evidence is insufficient.',one:'The output follows the demonstrated structure while using only facts from the new input.',few:'The classifier handles both common cases and boundary cases without copying labels mechanically from the nearest example.',structure:'The output passes schema validation and a separate evidence check; missing values are represented exactly as specified.',grounding:'Each material claim is supported by an accessible, applicable source passage and the approved revision is unambiguous.',decompose:'Intermediate artifacts retain IDs and units; a missing prerequisite stops the dependent step.',cot:'The reported formula and units can be checked independently; the answer distinguishes assumptions from measurements.',consistency:'The aggregation procedure is reproducible and the selected answer passes an independent check.',tree:'The chosen branch satisfies hard constraints and has a documented evaluation basis beyond model preference.',chain:'Every stage consumes a validated artifact and failures cannot silently propagate to the final report.',critique:'Every correction addresses a quoted failure against the rubric and remains supported by the source.',react:'Tool calls stay within allowed schemas and permissions, and conclusions refer to actual returned observations.',eval:'Results include held-out performance, critical failures, configuration, latency, and cost rather than only a favorable anecdote.',image:'The main subject and intended relationship are legible; geometry is reviewed and the image is labeled illustrative.',reference:'The intended region changes while key invariants are inspected against the original, not assumed preserved.',video:'Each shot has a clear action, coherent motion, and no unexplained geometry or identity change.',continuity:'Subject, environment, palette, and timing remain coherent across the assembled sequence.',injection:'The factual content is usable, the injected instruction is not followed, and no unauthorized tool action occurs.',leaking:'Protected configuration and data remain undisclosed; secrets were never included unnecessarily.',jailbreak:'The application continues the permitted task while retaining its behavior boundaries under adversarial reframing.'};
for(const t of TECHNIQUES)t.acceptance=LESSON_ACCEPTANCE[t.id]||(t.id==='tests-first'?'Tests cover meaningful behavior and boundary cases, fail for the known defect, and pass for the implementation.':'The proposed change meets its explicit acceptance criteria; the report identifies checks actually executed and any remaining uncertainty.');
